/* =========================================================
   FEUGEE MOGRAPH - plugin-only styles
   Everything here sits behind an .fgm-* class, so the shared
   panel.css stays byte-identical across the suite.
   ========================================================= */

/* ---------------------------------------------------------
   CONTROLLER PICKER + LINK / UNLINK
   --------------------------------------------------------- */
.fgm-link {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  gap: 5px;
  align-items: stretch;
}

/* UI Kit: a chip is icon left, label right */
.fgm-link .tile.chip { flex-direction: row; gap: 5px; padding: 4px 9px; }

.fgm-select {
  min-width: 0;
  height: 26px;
  padding: 0 24px 0 8px;
  background-color: var(--field);
  background-image: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%237b7b88' stroke-width='2.4' stroke-linecap='round' stroke-linejoin='round'%3E%3Cpath d='m6 9 6 6 6-6'/%3E%3C/svg%3E");
  background-repeat: no-repeat;
  background-position: right 7px center;
  background-size: 11px 11px;
  border: 1px solid var(--stroke);
  border-radius: 4px;
  color: var(--text);
  font-weight: 600;
  font-size: 9.5px;
  line-height: 1.2;
  font-family: inherit;
  -webkit-appearance: none;
  appearance: none;
  outline: none;
  cursor: pointer;
  text-overflow: ellipsis;
  transition: border-color 0.13s ease, box-shadow 0.13s ease;
}

.fgm-select:hover { border-color: var(--accent); }
.fgm-select:focus { border-color: var(--accent); box-shadow: 0 0 0 2px var(--accent-dim); }
.fgm-select option { background: var(--card); color: var(--text); }

/* ---------------------------------------------------------
   DEFAULT PROPERTY TOGGLES
   --------------------------------------------------------- */
.fgm-checks {
  display: grid;
  grid-template-columns: repeat(4, auto);
  justify-content: start;
  gap: 4px 12px;
  margin-bottom: 8px;
}

.fgm-checks .check { margin-bottom: 0; }

.check.fgm-gap { margin: 8px 0 0; }

/* ---------------------------------------------------------
   CONTROLLERS IN THIS COMP
   --------------------------------------------------------- */
.fgm-list {
  display: grid;
  gap: 4px;
}

.fgm-row {
  display: grid;
  grid-template-columns: 8px minmax(0, 1fr) auto;
  align-items: center;
  gap: 7px;
  min-height: 26px;
  padding: 4px 8px;
  background: var(--tile);
  border: 1px solid var(--stroke);
  border-radius: 4px;
  color: var(--text-dim);
  font-size: 9.5px;
  font-family: inherit;
  text-align: left;
  cursor: pointer;
  transition: background 0.13s ease, border-color 0.13s ease, color 0.13s ease;
}

.fgm-row:hover { background: var(--tile-hover); border-color: var(--accent); color: var(--text); }
.fgm-row.is-on { background: var(--accent-dim); border-color: var(--accent); color: var(--text); }

.fgm-row .dot {
  width: 7px;
  height: 7px;
  border-radius: 2px;
  background: var(--orange);
}

.fgm-row.effector .dot { background: var(--blue); border-radius: 50%; }

.fgm-row .name {
  font-weight: 700;
  letter-spacing: 0.3px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.fgm-row .count {
  color: var(--text-muted);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.fgm-empty {
  margin: 0;
  padding: 8px;
  border: 1px dashed var(--stroke);
  border-radius: 4px;
  font-size: 9.5px;
  line-height: 1.4;
  color: var(--text-muted);
}

@media (max-width: 250px) {
  .fgm-checks { grid-template-columns: repeat(2, auto); }
}

